const canvas=document.getElementById('opening-snow'),ctx=canvas.getContext('2d');let w,h,flakes=[];
function resize(){w=innerWidth;h=innerHeight;canvas.width=Math.round(w*3);canvas.height=Math.round(h*3);ctx.setTransform(3,0,0,3,0,0);flakes=Array.from({length:160},()=>({x:Math.random()*w,y:Math.random()*h,r:.45+Math.random()*2.1,v:9+Math.random()*24,phase:Math.random()*6.28}));}resize();addEventListener('resize',resize);let last=performance.now();
function frame(now){const dt=Math.min(.05,(now-last)/1000);last=now;ctx.clearRect(0,0,w,h);for(const f of flakes){f.y+=f.v*dt;f.x+=Math.sin(now*.0002+f.phase)*dt*7;if(f.y>h+4){f.y=-4;f.x=Math.random()*w;}ctx.beginPath();ctx.arc(f.x,f.y,f.r,0,Math.PI*2);ctx.fillStyle='rgba(240,248,255,'+(.25+f.r*.19)+')';ctx.fill();}requestAnimationFrame(frame);}requestAnimationFrame(frame);
addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==parent)return;const d=e.data;if(d?.type==='city:progress'){document.getElementById('load-bar').value=d.completed;document.getElementById('load-percent').textContent=Math.round(d.completed/9*100)+'%';document.getElementById('load-detail').textContent=d.message;document.getElementById('opening-hud').setAttribute('aria-label',d.message);}if(d?.type==='city:title'){document.getElementById('opening-title').textContent=d.title;document.getElementById('opening-en').textContent=d.english;}});
